#!/usr/bin/env python3
"""KCI 투고본 조판 — 진강 이중시장 장르동학 (2026-09-06 신판).

- 인용 양식: 글로벌문화콘텐츠학회식 본문내주 (저자 연도: 쪽) + 참고문헌.
- 용지: A4 그대로(판형 미조정), 기준본 폰트·포인트만 준수(Noto Sans CJK, 본문 10.5pt),
  줄간격은 별도 지정하지 않음(교수 지시).
- 무표식 조판: keepNext/keepLines/pageBreakBefore/widowControl/numPr 금지.
- 전 수치는 v2b_*·v2c_fig*·v2_gap_* 검증 산출물과 일치. 목표 분량: 200자 원고지 130매 수준.
"""
from pathlib import Path
from docx import Document
from docx.shared import Pt, Inches
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT

PROJ = Path(__file__).resolve().parent.parent
FIG = PROJ / "figures"
OUT = PROJ / "05_final" / "진강문학성_이중시장_장르동학_KCI투고본_20260906.docx"

doc = Document()
st = doc.styles["Normal"]
st.font.name = "Noto Sans CJK KR"
st.font.size = Pt(10.5)
C = WD_ALIGN_PARAGRAPH.CENTER

BODY_CHARS = 0

def para(text, bold=False, size=None, align=None, count=True):
    global BODY_CHARS
    p = doc.add_paragraph()
    if align:
        p.alignment = align
    r = p.add_run(text)
    r.bold = bold
    if size:
        r.font.size = Pt(size)
    if count:
        BODY_CHARS += len(text)
    return p

def caption(text):
    para(text, size=9.5, align=C, count=False)

def table(rows):
    t = doc.add_table(rows=len(rows), cols=len(rows[0]))
    t.style = doc.styles["Table Grid"]
    t.alignment = WD_TABLE_ALIGNMENT.CENTER
    for i, row in enumerate(rows):
        for j, val in enumerate(row):
            cell = t.cell(i, j)
            cell.text = ""
            p = cell.paragraphs[0]
            p.alignment = C
            r = p.add_run(str(val))
            r.font.size = Pt(9.5)
            if i == 0:
                r.bold = True
    return t

def figure(path, cap, width=5.9):
    p = doc.add_paragraph()
    p.alignment = C
    p.add_run().add_picture(str(path), width=Inches(width))
    caption(cap)

# ══════════ 표제부 ══════════
para("진강문학성 원창·파생 이중시장의 장르 동학과 정책 국면", bold=True, size=14, align=C, count=False)
para("― 2003–2026년 연도별 전수 메타데이터(386만 건)의 분석, 변곡점-정책 연동 추론, 수집 편향 검증 ―", size=11, align=C, count=False)
para("류호현", align=C, count=False)
para("", count=False)
para("목 차", bold=True, align=C, count=False)
for t in ["1. 서론", "2. 자료와 방법: 전수 재수집과 연도 필터의 체계적 누락",
          "3. 원창·파생 이중시장의 장르 추세", "4. 장르지형 재편과 정책 국면: 변곡점별 연동 분석",
          "5. 제목 키워드: 관습 장치와 유행어의 동기화", "6. 작가 동학과 소비 집중", "7. 결론"]:
    para(t, align=C, count=False)
para("", count=False)

# ══════════ 1. 서론 ══════════
para("1. 서론", bold=True, size=12)
para("중국 여성향 웹소설 플랫폼 진강문학성(晋江文学城)은 2003년 개설 이래 전 시기·전 작품의 목록 메타데이터를 공개해 온, 중국 웹소설 생태계에서 거의 유일하게 전수 관측이 가능한 플랫폼이다. 국내 연구 역시 진강을 중국 여성향 창작의 거점으로 지목해 왔다. 김승원(2025: 30)은 진강의 설립을 중국 BL 문화의 형성과 전개에 결정적인 전환점으로 평가하며, 김혜주(2024: 155)는 2003년부터 2010년 사이 진강에서 '순애(纯爱)' 키워드를 단 탐미소설이 500편에서 42,600편으로 증가했음을 소개한다. 필자는 선행 연구에서 2003–2024년 연재 데이터의 크롤링을 통해, 여성향 웹소설의 장르지형이 로맨스·관계성 중심에서 다장르·서사성 중심으로 재편되고 있으며 이 재편이 플랫폼 내부 동학만이 아니라 국가 개입과 직접적으로 연동되어 있음을 시사함을 논한 바 있다(류호현 2025: 193). 본 연구는 그 후속 작업으로, 2026년 7월 재수집한 연도별 전수 메타데이터 3,856,274건(2003–2026)을 대상으로 네 가지 과제를 수행한다.")
para("첫째, 카탈로그를 원창(原创)과 파생(衍生)의 두 시장으로 분리해 장르 추세를 계측한다. 선행 연구는 오리지널(원창) 작품을 분석 모수로 삼았으므로(류호현 2025: 179), 원창 시장의 추세에 대해 본 연구가 더하는 것은 별도 시점의 독립 재수집에 의한 재검증과 2026년까지의 연장이다. 본 연구의 실질적 신규 기여는 파생 시장에 있다. 원창과 파생은 창작 관습, 독자층, 법적 지위가 상이한 별개의 시장이지만, 파생 시장을 독립 모수로 세운 분석은 선행 연구에 없었고, 실제로 뒤에서 확인하듯 파생 시장의 가장 극적인 구조 변동은 원창 중심의 분석에서는 관측되지 않았다. 둘째, 이중시장 분해로 특정된 장르지형의 주요 변곡점 각각에 대해, 동시기 중국의 관련 정책 공시와 플랫폼·팬덤 사건을 대조하고 가능한 추론을 제시한다. 사건의 선후관계가 인과관계를 보증하지 않는다는 원칙을 견지하되, 공식 문건과 보도, 그리고 팬덤 연구가 기록한 반응까지 층위를 구분해 검토함으로써, 시점의 동조가 어떤 메커니즘을 경유했을 법한지를 가설의 자격으로 논한다. 셋째, 작품 제목이라는 표면 텍스트에서 장르별 관습 키워드와 연도별 신생 키워드를 추출해, 웹소설 제목이 장르 장치와 사회적 유행어를 흡수하는 리듬을 계측한다. 넷째, 시기별·장르별 작가의 유입과 이탈, 그리고 수용(작품적분)의 집중도를 추적해 플랫폼 창작 생태의 구조를 규명한다.")
para("이에 앞서 본 연구는 데이터 수집 방법 자체를 검증 대상으로 삼는다. 연도 필터 기반 전수 수집이 표방하는 '전수'가 실제로는 무엇을 체계적으로 누락하는지를 독립 수집으로 실측했으며, 그 결과는 본 연구를 포함한 플랫폼 메타데이터 연구 일반의 해석 한계를 규정한다. 필자는 선행 연구에서 이미 '여존(女尊)' 카테고리의 생성과 폐기처럼 플랫폼 데이터에 모종의 조정이 가해졌을 가능성을 지적하고, 플랫폼 데이터가 개설 초기 이래의 모든 현상을 충실히 담고 있다는 보장이 없음을 방법론적 전제로 명시한 바 있다(류호현 2025: 176). 본 연구는 그 전제를 실측의 수준으로 끌어올린다. 데이터의 발견과 방법의 검증, 그리고 정책 국면과의 대조를 한 논문 안에서 함께 제시하는 것은, 플랫폼이 제공하는 데이터가 중립적 관측창이 아니라 그 자체로 해석되어야 할 제도적 구성물이라는 문제의식을 방법론 층위로 확장하는 작업이다.")
para("이상의 과제는 다음의 연구 질문으로 집약된다. 원창과 파생이라는 두 시장은 각각 어떤 리듬으로 재편되어 왔으며, 그 재편의 변곡점들은 어떤 정책·플랫폼 국면과 동조하는가. 그리고 그 동조를 매개했을 법한 메커니즘은 분류 체계의 개입인가, 창작·게시 행동의 변화인가, 아니면 표현 수요의 우회인가. 이 질문에 답하기 위해서는 개별 사례나 표본이 아니라 전수 규모의 카탈로그가, 그리고 단일 시점이 아니라 수집 방법의 편향까지 통제된 시계열이 필요하다. 본 연구가 방법 검증에 상당한 지면을 할애하는 이유가 여기에 있다.")
para("국내외 선행 연구의 지형 위에서 본 연구의 위치는 다음과 같다. 중국 웹소설의 장르 층위에서는 인터넷 무협에서 '무'와 '협'이 배경적 요소로 추상화되고 장르 간 융합이 일반화되었다는 진단(최재용 2022: 160)과, 선협 로맨스를 중국 특유의 복합 장르로 보고 그 크로스미디어 확장을 추적한 논의(정유경·한혜원 2019: 87)가 축적되어 있다. BL·탐미 층위에서는 장르의 본토화 과정을 통사적으로 정리한 연구(김혜주 2024)와, 규제 국면에서 팬덤이 해외 플랫폼 이동·암호화된 표현·경제적 실천으로 대응하며 '하위 공론장'을 형성한다는 분석(김승원 2025)이 최근 제출되었다. 플랫폼 데이터 방법 층위에서는 한중 웹소설 플랫폼의 베스트셀러 텍스트를 마이닝한 비교 연구(이희진 외 2023)가 있으나, 전수 카탈로그 규모에서 시장 분리와 수집 편향 검증까지 수행한 연구는 아직 없다. 본 연구는 이 세 층위를 하나의 전수 데이터 위에서 교차시킨다.")

# ══════════ 2. 자료와 방법 ══════════
para("2. 자료와 방법: 전수 재수집과 연도 필터의 체계적 누락", bold=True, size=12)
para("2.1. 자료와 최신성", bold=True)
para("본 연구의 1차 자료는 2026년 7월 11일부터 14일에 걸쳐 진강문학성 작품고(作品库) 공개 목록에서 발표연도 필터(2003–2026년, 24개 파티션)로 수집한 목록 메타데이터다. 수집 항목은 작가명, 작품명, 유형(원창성-성향-시대-장르-시각의 결합 표지), 진행상태, 자수, 작품적분, 발표시간이며, 작품 고유번호 기준으로 중복을 제거한 결과 3,856,274건이 확정되었다. 발표연도 결측은 0건이다. 유형 표지를 분해하면 원창 2,818,576건(73.1%), 파생 572,721건(14.9%), 원창성 미표기 464,977건(12.1%)으로 구성된다. 미표기분은 임의로 어느 시장에도 배정하지 않고 별도 층으로 유지하였으며, 이하의 시장별 수치에서 제외된다. 결측 행을 규칙 기반으로 어느 한쪽에 귀속시키는 처리는 시장별 구성비를 가공의 방향으로 밀어낼 위험이 있고, 12.1%라는 규모는 그 위험을 감수하기에 너무 크기 때문이다. 아울러 본 자료의 위상을 선행 연구와의 관계에서 명시해 둔다. 선행 연구의 2003–2024년 분석은 수집 당시의 집계표 기준 전체 2,794,048건 가운데 오리지널 IP 2,283,784건을 분석 모수로 삼았다(류호현 2025: 179). 본 자료는 그보다 늦은 시점에 2026년까지의 범위를 연도 필터로 재수집한 별도의 모수이므로, 두 수치는 단일 계열로 접합되지 않으며 본 연구의 모든 수치는 본 자료 기준으로 재계산된 것이다.")
para("자료의 최신성에 관해 부기한다. 2026년 7월 20일 이후 진강문학성은 목록의 깊은 페이지 접근을 약 100페이지로 제한하기 시작했고, 이 제한은 본고 최종 확인 시점(2026년 9월 6일)까지 유지되고 있다. 연도 필터를 포함한 어떤 필터 조합으로도 100페이지를 넘는 구간은 접근이 거부되므로, 재수집을 통한 데이터 갱신은 현재 연구자 일반에게 불가능하다. 따라서 본 연구가 사용하는 2026년 7월 수집분은 현시점에서 도달 가능한 최대의 전수 자료이며, 이 접근 정책의 변화 자체가 뒤에서 논할 플랫폼 데이터의 제도적 성격을 방증한다.")
para("2.2. 연도 필터의 체계적 누락", bold=True)
para("연도 필터 수집의 완전성을 검증하기 위해, 연도 축을 사용하지 않는 독립 수집을 별도로 수행했다(2026년 7월 18–20일). 독립 수집은 진행상태(완결/연재), 원창성, 주인공 시각, 시대 축을 조합해 각 실행 단위가 플랫폼의 페이지네이션 상한을 넘지 않도록 분할하는 설계를 취했으며, 단일 접속으로 2초 이상의 간격을 두고 요청하는 저부하 원칙과 페이지 원문·해시·수집시각의 보존을 통해 재현 가능성을 확보했다. 그 결과 완결작 파티션 전체와 연재작 두 개 파티션이 결손 없이 전량 수집되었고, 이 전량 수집분이 연도 수집분과의 대조 기준이 된다. 무필터 전체 목록은 45,329페이지였던 반면 24개 연도 필터의 페이지 합계는 39,171페이지로, 약 61만 5천 건의 작품이 어떤 연도 필터에도 포착되지 않는 것으로 추정되었다. 전량 수집이 완료된 세 파티션을 연도 수집분과 작품 고유번호로 대조한 결과는 <표 1>과 같다. 완결작의 누락률은 0.13%에 불과했으나 연재 중 작품의 누락률은 12.8–14.5%에 달했고, 누락된 작품의 83–93%는 목록상 발표일 자체가 결측이었다. 두 수집 시점 사이의 신규 발표분을 통제한 보정치에서도 이 격차는 유지된다.")
caption("<표 1> 진행상태별 연도 필터 누락률 (전량 수집 파티션 기준, 신규 발표분 보정)")
table([
    ["구분", "작품 수", "공백(보정)", "공백률", "완결작 대비", "공백 중 발표일 결측"],
    ["완결작", "884,539", "1,164", "0.13%", "1배", "25.5%"],
    ["연재·파생", "679,503", "98,238", "14.46%", "110배", "92.6%"],
    ["연재·원작(남주 시각)", "276,359", "35,461", "12.83%", "97배", "83.0%"],
])
para("", count=False)
para("요컨대 연도 필터는 발표일 정보가 없는 연재 중 작품을 구조적으로 누락하며, 그 결과 연도 기반 시계열은 최근 연도일수록 체계적으로 과소집계된다. 어느 시점에 관측하든 최근 연도의 작품일수록 연재 중일 확률이 높기 때문이다. 따라서 본 연구는 최근 1–2개 연도의 절대 총량 비교를 유보하고 구성비 중심으로 해석하며, 2026년은 7월 수집 기준 부분연도로 명시한다. 이 편향은 연도 필터를 사용하는 모든 플랫폼 메타데이터 연구에 적용되는 일반적 한계로, 선행 연구(류호현 2025)의 장기 추세 논증 자체를 뒤집지는 않으나 최근 연도 해석에는 명시적 유보가 필요함을 뜻한다.")
para("나아가 누락분의 성격도 실측으로 확인해 두었다. 전량 수집 파티션 안에서 누락 작품과 포착 작품의 장르 구성을 비교하면 양자는 동일하지 않으나, 편향의 방향이 본 연구의 핵심 명제를 보수적으로 만드는 쪽이다. 연재·파생 파티션의 누락분에서 기타연생(21.1% 대 13.6%)·경소설(17.0% 대 9.7%)·서방연생(10.0% 대 5.7%)의 비중이 포착분보다 높고 동방연생(27.6% 대 35.8%)은 낮으며, 연재·원작 파티션의 누락분에서는 극정(14.9% 대 6.4%)이 높다. 즉 누락 작품을 포함할 수 있었다면 파생 시장의 다원천화와 극정의 부상이라는 본 연구의 두 핵심 발견은 약화되는 것이 아니라 오히려 강화되었을 것이며, 본 연구의 추정치는 그 하한으로 읽을 수 있다. 앞서 언급한 접근 제한으로 이 누락분의 전량 확보는 현재 불가능하므로, 계량된 편향의 방향과 상한을 제시하는 것이 도달 가능한 최선이며, 본 연구는 그 계측 자체를 방법론적 기여로 삼는다.")
para("2.3. 분석 방법", bold=True)
para("장르 추세는 시장별·연도별 장르 구성비로 산출했다. 웹소설의 제목·장르 텍스트에 대한 마이닝은 한중 플랫폼 베스트셀러 비교 연구(이희진 외 2023)에서 시도된 바 있으며, 본 연구는 그 접근을 베스트셀러 표본이 아닌 전수 카탈로그 규모로 확장한다. 제목 키워드는 중국어 2–3자 연쇄(n-gram)를 전수 추출하되 불용자를 제거하고, 연도별 신생 키워드는 직전 3년 평균 대비 성장배수와 절대 건수 하한을 함께 적용해 판정했다. 작가 동학은 다섯 시기(2003–09, 2010–16, 2017–19, 2020–23, 2024–26)에 대해 시기별 활동 작가 집합의 데뷔·유입·이탈·잔존을 계산했고, 수용 집중은 작품적분 상위 1%·10% 작품의 적분 점유율로 계측했다. 작품적분은 수집 시점의 누적치이므로 구작에 유리한 편향이 있어 시기 내 상대 비교로만 사용한다. 정책 국면 대조는 국무원·국가신문출판서(광전총국 포함 전신 기구)·중앙망신판·전국 소황타비 판공실의 공식 공시를 1차 전거로 삼고, 언론 보도와 팬덤 연구를 보조 층위로 구분해 인용한다. 모든 수치는 수집·정제·분석 스크립트와 집계 산출 파일로 재현 가능하며, 수집 명세·분해 규칙 코드북·수치 검증표를 포함한 재현 패키지를 공개 저장소(https://github.com/tgrlyu/jjwxc-dual-market-genre-dynamics)에 공개한다. 작품 단위 원자료는 필명 정보 보호와 재수집 불가능한 자료의 성격을 고려해 연구 목적의 합리적 요청 시 제공한다. 데이터 수집·정제·분석·시각화 스크립트의 작성과 수치 검증 체계 구축에는 AI 코딩 보조 도구(Anthropic Claude)를 활용하였으며, 연구 설계와 해석, 원고 집필, 표본 검수와 최종 판단은 저자가 수행하였다.")

# ══════════ 3. 이중시장 장르 추세 ══════════
para("3. 원창·파생 이중시장의 장르 추세", bold=True, size=12)
para("3.1. 원창 시장: 로맨스의 하락과 극정의 흡수", bold=True)
para("원창 시장에서 애정(爱情) 장르의 구성비는 2003년 80.8%에서 2010년 88.2%로 정점을 찍은 뒤 지속적으로 하락해 2024년 56.4%에 이르렀다. 정점 대비 31.8%p의 하락이다. <그림 1>이 보여주듯 이 공백을 흡수한 것은 극정(剧情)이다. 극정은 2020년 9.0%에서 2024년 14.6%로 상승해 원창 시장의 확고한 2위 장르로 자리잡았고, 경소설(轻小说)은 2022년 7.0%를 정점으로 완만히 하락했으며, 선협(仙侠)은 2024–26년 7%대에 안착했다. 하락의 궤적을 세분하면 국면이 드러난다. 애정은 2017년까지 80%를 상회하는 수준을 유지하다가(2008–2014년 84.1–88.2%, 2015–2017년 81.9–83.3%) 2018년 74.2%로 처음 크게 꺾였고, 2019년 68.1%에서 2023년 59.5%까지 내려간 뒤 2024년 56.4%에 이르렀다. 즉 하락은 완만한 장기 추세가 아니라 2018년을 기점으로 가속된 것이다. 극정의 도약(2019년 이후), 경소설의 성장(2018년 이후)이 모두 같은 기점 이후에 몰려 있다는 점에서, 2018년 전후는 원창 시장 장르 구성의 분수령이라 할 수 있다. 여기서 <그림 1>의 위상을 명확히 해 둔다. 원창 시장의 장르 구성비 추이 자체는 선행 연구의 그림 2가 이미 오리지널 모수로 제시한 것으로(류호현 2025: 182), 본 그림은 그것을 별도 시점의 독립 재수집으로 재검증하고 2026년까지 연장한 것이다. 극정이 2019–2020년 사이 로맨스를 제외한 기타 모든 장르를 추월했다는 선행 관찰(류호현 2025: 183) 역시 본 자료에서 재확인된다. 별도 수집이 같은 궤적을 재현한다는 사실은, 2.2절에서 논한 수집 편향이 핵심 추세를 왜곡하지 않음을 보여주는 강건성 근거이기도 하다. 한편 2025–26년(2025년은 완결 연도이나 연재 편향의 영향권에 있고, 2026년은 부분연도다) 애정이 58%대로 소폭 회복한 것은 2.2절의 편향, 곧 연재 중 작품의 과소 포착과 결부해 신중히 읽어야 한다. 누락분에서 극정 비중이 높다는 실측을 고려하면 이 회복분의 일부는 표본 구성의 산물일 수 있다.")
para("초기 상위 장르였던 무협(武侠)이 주변화되고 그 자리에 선협이 들어선 궤적도 뚜렷하다. 무협은 2003년 원창 3위(5.6%)였으나 이후 지속적으로 축소되어 상위 장르 목록에서 사라졌고, 선협이 2010년대 중반 이후 그 위치를 대체했다. 이는 인터넷 무협에서 '무'와 '협'이 배경적 요소로 추상화되고 장르 간 융합이 일반화되었다는 진단(최재용 2022: 160), 그리고 선협 로맨스를 신선·선계를 서사 요소로 활용하는 중국 특유의 복합 장르로 보는 논의(정유경·한혜원 2019: 87)와 부합한다. 장르의 소멸이 아니라 요소화, 곧 장르 명칭의 지위를 잃되 서사 자원으로 흡수되는 경로가 원창 시장 전수 데이터에서 관측되는 것이다.")
figure(FIG / "fig1_original_genre_trends.png", "<그림 1> 원창 시장 주요 장르 구성비 추이 (2003–2026). 류호현(2025) 그림 2의 독립 재수집 재검증·연장")
para("", count=False)
para("3.2. 파생 시장: 팬덤 원천의 다변화", bold=True)
para("파생 시장은 원창과 전혀 다른 재편을 겪었다. <그림 2>가 보여주듯 동방연생(东方衍生), 곧 중화권 원작 기반 2차 창작은 2009년부터 2017년까지 파생 시장의 85–96%를 점하는 압도적 단일 축이었다(2010년 95.8%). 그러나 이 구조는 점진적으로가 아니라 급격하게 무너졌다. 동방연생의 구성비는 2017년 85.0%에서 2018년 65.9%, 2019년 30.6%로 불과 2년 만에 붕괴했고, 이후 어느 원천도 압도하지 못하는 다원천 구조로 재편되었다. 2024년의 구성은 기타연생(其他衍生) 34.8%, 경소설(轻小说) 24.0%, 동방연생 23.6%, 서방연생(西方衍生) 14.3%다. 파생 창작의 참조 체계가 중화권 단일 축에서 일본 ACGN 문화와 기타 글로벌 원천으로 다변화된 것이다.")
figure(FIG / "fig2_derivative_recomposition.png", "<그림 2> 파생 시장 구성비 추이 (2003–2026)")
para("파생 시장의 성향 구성 또한 통념을 교정한다. 파생 창작은 흔히 BL 중심 공간으로 간주되지만, 성향 표지 기준으로 파생 시장에서는 소표본 초기(2003–2006년, 연 132–4,220건)에만 순애가 앞섰을 뿐, 규모가 갖춰진 2007년 이후 관측 전 기간에 걸쳐 언정이 1위를 유지했다(<그림 3>). 언정은 2010년 50.1%, 2017년 52.0%, 2024년 41.8%로 완만히 하락했을 뿐이며, 순애는 2010년 44.1%에서 2024년 23.9%로 오히려 크게 축소되었다. 파생 시장의 재편은 순애의 확장이 아니라 원천의 다변화와 순애 비중의 축소가 동시에 일어난 과정이었던 것이다. 이 구조 변화는 원창 시장을 분석 모수로 삼은 선행 연구의 범위 밖에 있던 것으로, 파생 시장의 독립 모수화가 산출한 독자적 발견이다. 붕괴의 시점(2018–19년)이 어떤 국면과 겹치는지, 그리고 그것이 창작 경향의 변화인지 플랫폼 분류 체계의 개입인지의 문제는 다음 장에서 정책 연표와 함께 본격적으로 검토한다. 여기서 확정할 수 있는 것은 두 가지다. 파생 시장의 트랜스내셔널화는 원창 시장의 장르 다양화와 별개의 리듬으로, 그리고 훨씬 급격한 형태로 진행되었다는 것, 그리고 그 결과 2020년대의 진강 파생 시장은 더 이상 중화권 원작의 팬덤 공간이 아니라 다원천 참조 체계의 공간이 되었다는 것이다. 파생 시장을 독립 모수로 세우는 순간에만 보이는 이 재편이야말로, 원창과 파생을 별개의 시장으로 다루어야 한다는 본 연구 설계의 실증적 정당화다.")
figure(FIG / "fig5_derivative_orientation_trends.png", "<그림 3> 파생 시장 성향 구성비 추이 (2003–2026). 초기 연도는 소표본(2003년 132건)으로 변동성이 큼")
para("", count=False)
para("3.3. 성향 축의 재편: 언정의 장기 하락과 순애의 규제 충격", bold=True)
para("원창 시장의 성향(性向) 구성은 선행 연구가 이미 오리지널 모수로 분석한 축이다(류호현 2025: 186-187). 본 연구의 독립 재수집은 그 궤적을 재현하고 2026년까지 연장하는데, 요약하면 다음과 같다. 원창 시장에서 언정(言情)의 구성비는 2003년 89.1%에서 2010년 69.6%, 2015년 61.3%, 2020년 48.3%로 하락해 2020년에 처음 절반 아래로 내려왔고, 2024년 44.8%, 2026년(부분연도) 40.2%에 이른다. 그 대칭 항이 순애(纯爱)다. 순애는 2010년 24.2%에서 꾸준히 상승해 2021년 39.2%로 정점을 찍는다. 무CP는 2015년 이후 7–10% 구간에서 안정적으로 유지되며 관계 표지 없는 서사의 상수적 수요를 보여주고, 백합은 낮은 수준에서 완만히 성장해 왔다. 다원(多元)은 신설 직후인 2024년 4.0%에서 2025년 7.0%로 빠르게 확대되는데, 4장에서 논하듯 이 확산에는 소급 재분류가 수반된 것으로 보인다.")
para("이 시계열에서 가장 선명한 단절은 2021년과 2022년 사이에 있다. 순애는 2021년 39.2%에서 2022년 30.6%로 8.6%p 급락했고, 같은 구간에서 언정은 45.8%에서 54.4%로 8.6%p 반등했다. 두 성향의 증감이 정확히 대칭을 이루는 이 단절은, 선행 연구가 확인했던 2021년 9월 전후의 순애 급감과 언정 반등(류호현 2025: 187)을 별도 시점의 독립 재수집에서 거의 같은 진폭(선행 관측 약 8.0%p, 본 자료 8.6%p)으로 재현하는 것이다. 재수집이 같은 단절을 같은 크기로 재현한다는 사실은 이 충격 관측의 강건성을 보여준다. 이 시점이 어떤 국면인지는 다음 장에서 다룬다. 여기서 기록할 것은 반등이 일시적이었다는 사실이다. 언정은 2022년의 회복 이후 다시 하락 궤도로 복귀해 2024년 44.8%까지 내려왔고, 순애는 2024년 34.1%, 2026년 38.2%로 회복했다. 충격은 실재했으나 장기 추세를 되돌리지는 못한 것이다.")
para("", count=False)

# ══════════ 4. 정책 국면 (신설) ══════════
para("4. 장르지형 재편과 정책 국면: 변곡점별 연동 분석", bold=True, size=12)
para("본 장은 앞서 확인한 장르지형의 주요 변곡점 각각을 동시기 정책 공시·플랫폼 사건·팬덤 반응과 대조한다. 방법적 원칙을 먼저 명시한다. 첫째, 사건의 선후관계는 인과관계를 보증하지 않으며, 목록 메타데이터만으로는 관측된 변화가 플랫폼의 일괄 조치인지, 작가들의 자발적 행동 변화인지, 분류 체계의 재편인지 판별할 수 없다. 둘째, 따라서 본 장의 서술은 검증된 데이터 신호, 공식 문건으로 확인되는 제도적 사실, 보도로 확인되는 플랫폼 조치, 연구·언론이 기록한 팬덤의 반응과 통설을 층위별로 구분해 제시하고, 이들을 잇는 해석은 가설의 자격으로만 제출한다. 셋째, 선행 연구의 사실 서술 역시 그대로 신뢰하지 않는다. 정책·플랫폼 조치에 관한 서술은 가능한 한 공식 문건과 당대 보도로 교차 확인했으며, 교차 확인이 닿지 않아 단일 연구의 서술에 의존하는 대목은 본문에서 그 귀속을 명시해 사실 층위와 구분한다. 넷째, 그럼에도 이 대조가 필요한 이유는, 여러 변곡점에서 시점의 동조가 우연으로 치부하기 어려울 만큼 반복적으로, 그리고 메커니즘을 시사하는 구체적 조치와 함께 나타나기 때문이다.")
para("논의에 앞서 본 장이 다루는 제도·플랫폼 연표를 <표 2>로 총괄한다. 각 행은 공식 문건 또는 보도로 확인되는 사건이며, 마지막 열은 본 연구 데이터에서 동시기에 관측되는 변곡을 요약한 것이다. 다시 강조하지만 이 대응은 시점의 동조이지 인과의 확정이 아니다.")
